<script setup lang="ts">
import {qualityText as qt} from '../shared/i18n'

import {defineAsyncComponent,reactive} from 'vue'
import {useTaskPage} from '../hooks/useTaskPage'
import {taskStates,time,type Task} from '../shared/types'
const Schedule=defineAsyncComponent(()=>import('./TaskSchedule.vue'))
const props=defineProps<{level:number}>(),vm=reactive(useTaskPage(props.level))
</script>
<template><a-card :title="(level===1?qt('company'):qt('project2'))+qt('inspectionTasks')"><template #extra><a-space><a-popconfirm v-if="vm.selectedKeys.length&&vm.can('quality-task','delete')" :title="qt('deleteSelected')" @confirm="vm.removeSelected"><a-button danger>{{qt('deleteSelected')}}</a-button></a-popconfirm><a-button @click="vm.load" :loading="vm.loading">{{qt('refresh')}}</a-button><a-button v-if="vm.can('quality-task','save')" type="primary" @click="vm.start()">{{qt('newTask')}}</a-button></a-space></template>
 <a-alert v-if="vm.error" type="error" :message="vm.error" show-icon /><a-space wrap style="margin:16px 0"><a-select v-model:value="vm.projectId" show-search option-filter-prop="label" :options="vm.projects.map(p=>({value:p.id,label:p.name}))" :placeholder="qt('allBusinessProjects')" allow-clear style="width:230px" /><a-select v-model:value="vm.status" :options="Object.entries(taskStates).map(([value,label])=>({value:Number(value),label}))" :placeholder="qt('allStatuses')" allow-clear style="width:160px" /><a-input-search v-model:value="vm.name" :placeholder="qt('taskName')" @search="vm.search" /></a-space>
 <a-table :row-selection="{selectedRowKeys:vm.selectedKeys,onChange:(keys:unknown[])=>vm.selectedKeys=keys.map(String),getCheckboxProps:(row:Task)=>({disabled:row.taskStatus!==0})}" :data-source="vm.rows" :loading="vm.loading" row-key="id" :pagination="{current:vm.current,total:vm.total,pageSize:20,showSizeChanger:false}" :scroll="{x:'max-content'}" @change="(p:{current?:number})=>{vm.current=p.current||1;vm.load()}">
 <a-table-column :title="qt('taskName')" data-index="taskName" /><a-table-column :title="qt('businessProject')" data-index="projectName" /><a-table-column :title="qt('template')" data-index="templateName" /><a-table-column :title="qt('type')" key="type"><template #default="{record}">{{record.taskType===1?qt('temporaryTask'):qt('recurringTask')}}</template></a-table-column><a-table-column :title="qt('status')" key="status"><template #default="{record}"><a-tag :color="record.taskStatus===1?'blue':'default'">{{taskStates[record.taskStatus]}}</a-tag></template></a-table-column><a-table-column :title="qt('created')" key="time"><template #default="{record}">{{time(record.createTime)}}</template></a-table-column>
 <a-table-column :title="qt('actions')" key="actions"><template #default="{record}"><a-space><a-button type="link" @click="vm.start(record,true)">{{qt('details')}}</a-button><a-button type="link" @click="vm.showPlan(record)">{{qt('workSchedule')}}</a-button><template v-if="record.taskStatus===0"><a-button v-if="vm.can('quality-task','save')" type="link" @click="vm.start(record)">{{qt('edit')}}</a-button><a-popconfirm v-if="vm.can('quality-task','issue')" :title="qt('issueThisTaskItCannotBeEditedAfterIssue')" @confirm="vm.act(record,'issue')"><a-button type="link">{{qt('issue')}}</a-button></a-popconfirm><a-popconfirm v-if="vm.can('quality-task','delete')" :title="qt('deleteThisTask')" @confirm="vm.act(record,'delete')"><a-button danger type="link">{{qt('delete')}}</a-button></a-popconfirm></template><a-popconfirm v-if="[0,1].includes(record.taskStatus)&&vm.can('quality-task','close')" :title="qt('closeThisTaskAndStopFutureSchedules')" @confirm="vm.act(record,'close')"><a-button type="link" danger>{{qt('close')}}</a-button></a-popconfirm></a-space></template></a-table-column></a-table>
 <a-drawer v-model:open="vm.open" :title="vm.readonly?qt('taskDetails'):vm.form.id?qt('editTask'):qt('newTask')" width="820"><a-alert v-if="vm.error" type="error" :message="vm.error" show-icon /><a-form layout="vertical" :model="vm.form" :disabled="vm.readonly" @finish="vm.save">
 <a-form-item :label="qt('taskName')" name="taskName" :rules="[{required:true,message:qt('enterTheTaskName')}]"><a-input v-model:value="vm.form.taskName" :maxlength="128" /></a-form-item><a-form-item :label="qt('businessProject')" name="projectId" :rules="[{required:true,message:qt('selectABusinessProject')}]"><a-select v-model:value="vm.form.projectId" show-search option-filter-prop="label" :options="vm.projects.map(p=>({value:p.id,label:p.name}))" :disabled="!!vm.form.id" /></a-form-item><a-form-item :label="qt('taskTemplate')" name="templateId" :rules="[{required:true,message:qt('selectATemplate')}]"><a-select v-model:value="vm.form.templateId" :options="vm.templates.map(t=>({value:t.id,label:t.name}))" @change="vm.selectTemplate" /></a-form-item>
 <a-form-item :label="qt('inspectionRole')"><a-select v-model:value="vm.form.checkRole" :options="vm.roles.map(r=>({value:r.id,label:r.name}))" allow-clear /></a-form-item><a-divider orientation="left">{{qt('lineInspectors')}}</a-divider><a-form-item v-for="line in vm.lines" :key="line.id" :label="line.name"><a-select :value="vm.form.lineAssignees.find(a=>a.subjectParentId===line.id)?.inspectorId" :options="vm.candidates.map(p=>({value:p.id,label:p.name}))" show-search option-filter-prop="label" @change="(v:unknown)=>vm.setAssignee(line.id,v)" /></a-form-item>
 <a-collapse v-if="vm.form.configItems?.length"><a-collapse-panel key="deduct" :header="qt('checkItemsAndDeductionRules')"><a-form-item v-for="item in vm.form.configItems" :key="item.configId" :label="vm.snapshots.find(s=>s.configId===item.configId)?.contentName"><a-textarea v-model:value="item.deductionStandard" /></a-form-item></a-collapse-panel></a-collapse>
 <Schedule :form="vm.form" :readonly="vm.readonly" /><a-form-item :label="qt('remark')" style="margin-top:20px"><a-textarea v-model:value="vm.form.remark" /></a-form-item><a-button v-if="!vm.readonly" type="primary" html-type="submit" :loading="vm.saving">{{qt('saveTask')}}</a-button></a-form></a-drawer>
 <a-drawer v-model:open="vm.planOpen" :title="qt('workSchedule')" width="800"><a-table :data-source="vm.plan" row-key="id"><a-table-column :title="qt('generationTime')" key="time"><template #default="{record}">{{time(record.scheduledTime)}}</template></a-table-column><a-table-column :title="qt('cycleStart')" key="start"><template #default="{record}">{{time(record.cycleStartTime)}}</template></a-table-column><a-table-column :title="qt('cycleEnd')" key="end"><template #default="{record}">{{time(record.cycleEndTime)}}</template></a-table-column><a-table-column :title="qt('status')" key="status"><template #default="{record}">{{({0:qt('notIssued'),1:qt('pendingGeneration'),2:qt('generated'),3:qt('closed')} as Record<number,string>)[record.status]}}</template></a-table-column></a-table></a-drawer>
 </a-card></template>
